css:
body :where([data-bz-node="bp"]) .bz-block{padding:0}
body :where([data-bz-node="bp"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="bp"]>.bz-container{padding-inline:0}

body [data-bz-node="bp"]{background:#161616;padding:90px 0 79px;color:#fff;overflow:hidden}
body [data-bz-node="bp"]>.bz-container{max-width:var(--container)}
body [data-bz-node="bp-head"] .bz-headingblock{text-align:center}
body [data-bz-node="bp-head"] h2{font:700 36px/1.1 var(--font-heading);letter-spacing:-.01em;text-transform:uppercase;color:#fff;margin:0}
body [data-bz-node="bp-rail"]{display:flex;flex-wrap:wrap;justify-content:center;gap:16px;margin-top:78px}
body [data-bz-node^="bp-slide-"]{grid-column:auto;flex:0 0 190px;background:#1f1f1f;padding:10px 10px 0;box-sizing:border-box;text-align:center}
body [data-bz-node^="bp-slide-"] img{width:100%;aspect-ratio:1;object-fit:contain;background:#fff;border-radius:0;padding:8%;box-sizing:border-box}
body [data-bz-node^="bp-slide-"] figure{margin:0}
body [data-bz-node^="bp-name-"] p{font:700 11px/44px var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:#bbb;margin:0}
body [data-bz-node="bp-controls"]{display:block;margin-top:48px}
body [data-bz-node="bp-controls-col"]{display:flex;justify-content:center;gap:8px}
body [data-bz-node="bp-controls"] .bz-block{width:36px;height:36px}
body [data-bz-node="bp-prev"],body [data-bz-node="bp-next"]{background:var(--accent)}
body [data-bz-node="bp-prev"]:hover,body [data-bz-node="bp-next"]:hover{background:var(--accent-dark)}
body [data-bz-node="bp-prev"] a,body [data-bz-node="bp-next"] a,body [data-bz-node="bp-prev"] button,body [data-bz-node="bp-next"] button{display:flex;align-items:center;justify-content:center;width:36px;height:36px;border:0;background:none;padding:0;cursor:pointer}
body [data-bz-node="bp-prev"] img,body [data-bz-node="bp-next"] img{width:18px;height:18px}
body [data-bz-node="bp-prev"] figure,body [data-bz-node="bp-next"] figure{margin:0}

/* Coverflow — only once bp.js has staged it. Without JS (and in the editor) the logos are an in-flow row. */
body [data-bz-node="bp-rail"].is-staged{display:block;position:relative;height:311px;gap:0}
body [data-bz-node="bp-rail"].is-staged>.bz-col{position:absolute;left:50%;top:50%;transition:transform .45s ease,opacity .45s ease,width .45s ease,background-color .45s ease;opacity:0;pointer-events:none;transform:translate(-50%,-50%)}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="0"]{width:255px;padding:10px 10px 0;background:#2b2824;opacity:1;pointer-events:auto;z-index:3}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="0"] img{height:240px}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="0"] p{font-size:16px;line-height:61px;color:#fff;letter-spacing:.1em;height:61px}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-1"],body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="1"]{width:215px;padding:12px 12px 0;opacity:1;pointer-events:auto;z-index:2}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-1"] img,body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="1"] img{height:190px;opacity:.9}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-2"],body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="2"]{width:170px;padding:12px 12px 0;background:#1a1a1a;opacity:1;pointer-events:auto;z-index:1}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-2"] img,body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="2"] img{height:150px;opacity:.55}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-2"] p,body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="2"] p{color:#777}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-2"]{transform:translate(calc(-50% - 455px),-50%)}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-1"]{transform:translate(calc(-50% - 249px),-50%)}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="1"]{transform:translate(calc(-50% + 249px),-50%)}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="2"]{transform:translate(calc(-50% + 455px),-50%)}
body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="far"]{width:170px;opacity:0;transform:translate(-50%,-50%) scale(.6)}
@media (max-width:1100px){
  body [data-bz-node="bp"]{padding:64px 24px}
  body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-2"],body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="2"]{opacity:0;pointer-events:none}
  body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-1"]{transform:translate(calc(-50% - 240px),-50%)}
  body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="1"]{transform:translate(calc(-50% + 240px),-50%)}
}
@media (max-width:640px){
  body [data-bz-node="bp"]{padding:48px 0 48px}
  body [data-bz-node="bp-head"] h2{font-size:26px}
  body [data-bz-node="bp-rail"]{margin-top:40px}
  body [data-bz-node="bp-rail"].is-staged{height:300px}
  body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="0"]{width:220px}
  body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="0"] img{height:200px}
  body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-1"],body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="1"]{width:150px;opacity:.5}
  body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-1"] img,body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="1"] img{height:120px}
  body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="-1"]{transform:translate(calc(-50% - 175px),-50%)}
  body [data-bz-node="bp-rail"].is-staged>.bz-col[data-pos="1"]{transform:translate(calc(-50% + 175px),-50%)}
  body [data-bz-node="bp-controls"]{margin-top:32px}
}
@media (prefers-reduced-motion:reduce){body [data-bz-node="bp-rail"].is-staged>.bz-col{transition:none}}

