(function () {
  /* Coverflow for the brand partners band. The platform `carousel` behaviour is a
     scroll-snap rail and cannot centre-and-scale one slide, so this script only
     sets data-pos on each slide; every size and offset lives in the component CSS. */
  document.querySelectorAll('[data-bz-node="bp-rail"]').forEach(function (rail) {
    var slides = Array.prototype.slice.call(rail.children).filter(function (el) { return el.classList.contains('bz-col'); });
    var n = slides.length;
    if (n < 2) return;
    var root = rail.closest('[data-bz-node="bp"]') || document;
    var prev = root.querySelector('[data-bz-node="bp-prev"] a, [data-bz-node="bp-prev"] button');
    var next = root.querySelector('[data-bz-node="bp-next"] a, [data-bz-node="bp-next"] button');
    var active = Math.min(2, n - 1);
    if (n >= 3) active = Math.floor(n / 2);
    function layout() {
      var half = Math.floor(n / 2);
      slides.forEach(function (slide, i) {
        var d = ((i - active) % n + n) % n;
        if (d > half) d -= n;
        slide.setAttribute('data-pos', Math.abs(d) <= 2 ? String(d) : 'far');
        slide.setAttribute('aria-hidden', Math.abs(d) <= 2 ? 'false' : 'true');
      });
    }
    function go(step, e) { if (e) e.preventDefault(); active = (active + step + n) % n; layout(); }
    if (prev) { prev.setAttribute('aria-label', 'Previous brand'); prev.addEventListener('click', function (e) { go(-1, e); }); }
    if (next) { next.setAttribute('aria-label', 'Next brand'); next.addEventListener('click', function (e) { go(1, e); }); }
    slides.forEach(function (slide, i) {
      slide.addEventListener('click', function () { if (i !== active) { active = i; layout(); } });
    });
    rail.setAttribute('tabindex', '0');
    rail.setAttribute('role', 'group');
    rail.setAttribute('aria-label', 'Brand partners');
    rail.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowRight') go(1, e);
      if (e.key === 'ArrowLeft') go(-1, e);
    });
    layout();
    rail.classList.add('is-staged');
  });
})();
